# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.13.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.13"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.13/berth-darwin-arm64.tar.gz"
      sha256 "7a16711f8ecc2089798122617ab6d798188e0102a233b1a6016dcb918210f00d"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.13/berth-darwin-amd64.tar.gz"
      sha256 "9b57a83dc2c26e549ce7254c11c0d71da642d64fecd89d1d778d722bea61209e"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.13/berthd-darwin-arm64.tar.gz"
      sha256 "37af86f9be6db5dd99049d9cd260ea3c67c81d9eb52c936ac2ceab22da145d39"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.13/berthd-darwin-amd64.tar.gz"
      sha256 "eab74bbba6057d24e85079881e60babb680a837b3b145c5d5d2ad15a221a4190"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.13/berth-linux-arm64.tar.gz"
      sha256 "4d323578854d06d3f7637e426d64e31d4cf16bd83d5e0f677355f42fc9bd1d1e"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.13/berth-linux-amd64.tar.gz"
      sha256 "1b4c4b72feaec4323b6799a29c5d728e391c3a9be056932c94512b99e0dfb3ff"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
